nextflow_process {

    name "Test Process MALTEXTRACT"
    script "../main.nf"
    process "MALTEXTRACT"

    tag "modules"
    tag "modules_nfcore"
    tag "maltextract"

    test("test_maltextract") {
        def ncbi_taxmap
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            ncbi_taxmap = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/maltextract/ncbi_taxmap.zip')
        }

        when {
            process {
                """
                input[0] = [ [],
                    file(params.modules_testdata_base_path + 'delete_me/malt/test.rma6')
                ]
                input[1] = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/db/maltextract/taxon_list.txt')
                input[2] = file('${ncbi_taxmap}')
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    path("${process.out.results.get(0).get(1)}/ScanSummary.txt"),
                    path("${process.out.results.get(0).get(1)}/error.txt").text == "",
                    file("${process.out.results.get(0).get(1)}/log.txt").name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("test_maltextract - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [],
                    file(params.modules_testdata_base_path + 'delete_me/malt/test.rma6')
                ]
                input[1] = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/db/maltextract/taxon_list.txt')
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}
